<script setup lang="ts">import { onMounted, ref } from 'vue'; import { useRouter } from 'vue-router'; import { ApiError, customersApi, type Customer } from '../services/api'; import { useAuthStore } from '../stores/auth'; const auth=useAuthStore();const router=useRouter();const customers=ref<Customer[]>([]);const error=ref('');const name=ref('');const email=ref('');const phone=ref('');const form=ref();async function load(){try{customers.value=await customersApi.list(auth.token)}catch(e){error.value=e instanceof ApiError?e.message:'No fue posible cargar los clientes.'}}async function save(){const r=await form.value.validate();if(!r.valid)return;try{await customersApi.create({full_name:name.value,email:email.value,phone:phone.value},auth.token);name.value='';email.value='';phone.value='';await load()}catch(e){error.value=e instanceof ApiError?e.message:'No fue posible registrar el cliente.'}}onMounted(load)</script>
<template><v-app><v-app-bar color="primary"><v-app-bar-title><v-icon>mdi-account-group</v-icon> Clientes</v-app-bar-title><v-btn to="/panel">Panel</v-btn></v-app-bar><v-main><v-container class="py-10"><v-card v-if="!auth.isAuthenticated()" max-width="650" class="mx-auto"><v-card-title>Sección de clientes</v-card-title><v-card-text>Para proteger los datos personales, inicia sesión con una cuenta autorizada antes de consultar o registrar clientes.</v-card-text><v-card-actions><v-spacer/><v-btn to="/acceso" color="primary">Iniciar sesión</v-btn></v-card-actions></v-card><v-row v-else><v-col cols="12" md="4"><v-card><v-card-title>Registrar cliente</v-card-title><v-card-text><v-form ref="form" @submit.prevent="save"><v-text-field v-model="name" label="Nombre completo" :rules="[v=>v?.length>=3||'Campo requerido']"/><v-text-field v-model="email" label="Correo" :rules="[v=>/.+@.+\..+/.test(v)||'Correo inválido']"/><v-text-field v-model="phone" label="Teléfono" :rules="[v=>v?.length>=8||'Teléfono inválido']"/><v-btn type="submit" color="primary" block>Guardar</v-btn></v-form></v-card-text></v-card></v-col><v-col cols="12" md="8"><v-card><v-card-title>Clientes registrados</v-card-title><v-card-text><v-alert v-if="error" type="error">{{error}}</v-alert><v-table><thead><tr><th>Nombre</th><th>Correo</th><th>Teléfono</th></tr></thead><tbody><tr v-for="customer in customers" :key="customer.id"><td>{{customer.full_name}}</td><td>{{customer.email}}</td><td>{{customer.phone}}</td></tr></tbody></v-table></v-card-text></v-card></v-col></v-row></v-container></v-main></v-app></template>
